/* Shared progress copy and markup. No aggregation, graph or layout calls. */
(function(g){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number(n).toLocaleString('en-US');
const ref=s=>(String(s??'').match(/.{1,24}/g)||[]).map(esc).join('<wbr>');
function bar(s){if(!s.eligible)return'';return`<div class="progress-bar" role="img" aria-label="${s.learned} learned, ${s.notLearned} explicitly not learned, ${s.unknown} unknown, of ${s.eligible}">${[['learned',s.learned],['not-learned',s.notLearned],['unknown',s.unknown]].map(([name,count])=>`<span class="${name}" style="width:${100*count/s.eligible}%"></span>`).join('')}</div>`;}
const observed=s=>s.lastObserved?`<p class="progress-date">Last observed: <time datetime="${esc(s.lastObserved)}">${esc(s.lastObserved)}</time></p>`:'';
function official(s){return `<p class="official-course-progress">Official Hyperskill: ${s.state==='UNKNOWN'?'No complete Course snapshot':`${number(s.learned)} / ${number(s.eligible)} learned in the direct Course snapshot`}${s.lastObserved?` · <time datetime="${esc(s.lastObserved)}">${esc(s.lastObserved)}</time>`:''}</p>`;}
function completionStatus(s){return s?.completed===true?'<p class="completion-status"><b>Completed</b></p>':'';}
function completionEvidence(s){return s?.evidence.length?`<p>Completion evidence: ${s.completed===true?'Completed':s.completed===false?'Not completed':'Conflicting observations'}</p>${s.evidence.map(e=>`<p>${ref(e.source)}${e.evidence_id?' · '+ref(e.evidence_id):''} · <time datetime="${esc(e.observed_at)}">${esc(e.observed_at)}</time></p>`).join('')}`:'';}
function completionBar(count,total){return total>0?`<div class="progress-bar completion-bar" role="img" aria-label="${count} confirmed completed of ${total} associated Projects"><span class="learned" style="width:${100*count/total}%"></span></div>`:'';}
function coursePortfolio(a,id){const s=a.courseProjects(id);return `<div class="course-portfolio"><p>${s.state==='UNKNOWN'?'Project inventory unknown':s.state==='KNOWN_EMPTY'?'No associated projects':`<b>${number(s.completed)} / ${number(s.eligible)}</b> associated projects completed`}</p>${s.state==='KNOWN'?completionBar(s.completed,s.eligible):''}${completionStatus(a.completionStatus('course',id))}</div>`;}
function overview(a,course=null){const p=a.portfolio(),s=a.global(),cp=course==null?null:a.courseProjects(course);return `<div class="overview-metrics"><span class="overview-metric"><small>Topics learned</small><b>${number(s.learned)} / ${number(s.eligible)}</b><small>${number(s.verified)} verified</small>${bar(s)}</span><span class="overview-metric"><small>Projects completed</small><b>${number(p.completed_project_count)}</b></span>${cp?.state==='KNOWN'?`<span class="overview-metric"><small>Course Projects</small><b>${number(cp.completed)} / ${number(cp.eligible)} completed</b></span>`:''}${p.completed_course_count===null?'':`<span class="overview-metric"><small>Courses completed</small><b>${number(p.completed_course_count)}</b></span>`}</div>`;}
// Portfolio catalog definitions and provenance live only in optional details.
function portfolio(a){const p=a.portfolio();return `<div class="portfolio-completions"><p>Catalog: ${number(p.project_catalog_count)} projects · ${number(p.course_catalog_count)} courses. Catalog totals are not an enrolled plan or official overall completion.</p><p>${number(p.completed_project_count)} completed project${p.completed_project_count===1?'':'s'}${p.completed_course_count===null?' · No Course completion evidence':` · ${number(p.completed_course_count)} completed courses`}</p>${p.completed_project_ids.map(id=>`<p>${esc(a.scopeMaps.project.get(id).title)} · Project ${id}</p>${completionEvidence(a.completionStatus('project',id))}`).join('')}</div>`;}
function sourceEvidence(a,ids){
 const groups=new Map();for(const id of ids||[])for(const e of a.topic(id).learningEvidence){const kind=e.project_id?'Owner-attested Project '+e.project_id:'Direct observation',key=JSON.stringify([kind,e.source,e.observed_at]);if(!groups.has(key))groups.set(key,{kind,source:e.source,date:e.observed_at,ids:new Set()});groups.get(key).ids.add(id);}
 return [...groups.values()].map(e=>`<p>${esc(e.kind)} · ${ref(e.source)} · ${e.date?`<time datetime="${esc(e.date)}">${esc(e.date)}</time>`:'Date unknown'} · ${number(e.ids.size)} Topics</p>`).join('');
}
function cardDetails(title,s,denominator,{status=null,officialProgress=null,completion=null,identity='',sources=''}={}){
 return `<section><h3>${esc(title)}${identity?' · '+esc(identity):''}</h3><p>Topic denominator: ${esc(denominator)}${s.state==='UNKNOWN'?' · UNKNOWN':` · ${number(s.eligible)} distinct Topics`}</p>${s.state==='UNKNOWN'?'':`<p>${number(s.learned)} learned · ${number(s.notLearned)} explicitly not learned · ${number(s.unknown)} unknown</p><p>${number(s.verified)} verified · ${number(s.eligible-s.verified-s.verifiedUnknown)} explicitly not verified · ${number(s.verifiedUnknown)} verification unknown</p>`}${sources||observed(s)}${officialProgress?official(officialProgress):''}${status?.status?`<p>Observed status: ${esc(status.status)}${status.lastObserved?' · '+esc(status.lastObserved):''}</p>`:''}${completionEvidence(completion)}</section>`;
}
function dataDetails(content){return `<details data-progress-details><summary>Data details</summary><p class="progress-note">Bar segments: learned · explicitly not learned · unknown. Verification is independent.</p><p class="progress-note">Learning combines direct observations and owner-attested Project requirement Topics. Course and Stage completion require separate evidence.</p>${content}</details>`;}
function card(title,s,denominator,{requirements=false,status=null,officialProgress=null,completion=null,coursePortfolioMarkup='',details=true,identity='',sources=''}={}){
 const body=s.state==='UNKNOWN'?'<strong>Requirements unknown</strong>':s.eligible===0?`<strong>${requirements?'No required Topics':'No Topics'}</strong>`:`<strong>${number(s.learned)} / ${number(s.eligible)} learned</strong>${bar(s)}${s.verified?`<p>${number(s.verified)} verified</p>`:''}`;
 return `<section class="progress-card"${identity?` data-scope="${esc(identity)}"`:''}><h3>${esc(title)}</h3>${body}${completionStatus(completion)}${coursePortfolioMarkup}${details?dataDetails(cardDetails(title,s,denominator,{status,officialProgress,completion,identity,sources})):''}</section>`;
}
function scopeOptions(a,type,id){const row=a.scopeMaps[type].get(id),course=type==='course';return {requirements:!course,status:course?null:a.personalStatus(type,id),officialProgress:course?a.officialCourseProgress(id):null,completion:a.completionStatus(type,id),coursePortfolioMarkup:course?coursePortfolio(a,id):'',identity:type+' '+id,sources:sourceEvidence(a,row.explicit_topic_ids)};}
const denominator=type=>type==='course'?'All distinct explicit Course Topic IDs':type==='stage'?'Explicit Stage-local requirement Topics':'Distinct explicit Project study-plan requirement Topics';
function scopeCard(a,type,id,{details=true}={}){const row=a.scopeMaps[type].get(id),options=scopeOptions(a,type,id);return card(row.title,a.scope(type,id),denominator(type),{...options,completion:type==='course'?null:options.completion,details});}
function scopeDetails(a,type,id){const row=a.scopeMaps[type].get(id),cp=type==='course'?a.courseProjects(id):null;return cardDetails(row.title,a.scope(type,id),denominator(type),scopeOptions(a,type,id))+(cp?`<p>Project denominator: all distinct explicitly associated Project IDs · ${cp.state==='UNKNOWN'?'UNKNOWN':number(cp.eligible)+' projects'}${cp.evidence_id?' · '+ref(cp.evidence_id):''}</p>${cp.completed_project_ids?.length?'<p>Completed Project IDs: '+cp.completed_project_ids.join(', ')+'</p>':''}`:'');}
function panelDetails(a,{course,project,stage,topicIds=[]}){return dataDetails(cardDetails('Global Topics',a.global(),'All globally catalogued Topic IDs',{sources:sourceEvidence(a,topicIds)})+[ ['course',course],['project',project],['stage',stage] ].filter(([,id])=>id!=null).map(([type,id])=>scopeDetails(a,type,id)).join('')+portfolio(a));}
function scope(a,row){return `<section class="category-progress scope-progress">${scopeCard(a,row.scope_type,row.scope_id)}</section>`;}
function category(a,id,context=null){
 const kids=[...(a.children.get(id)||[])].filter(child=>a.categories.has(child)),title=a.categories.get(id).title,contextRow=context?a.scopeMaps[context.scope_type].get(context.scope_id):null;
 const global=a.category(id),local=context?a.categoryInScope(id,context.scope_type,context.scope_id):null,definition='All structural descendant Topic IDs, including secondary memberships';
 const evidence=cardDetails(title,global,definition,{identity:'category '+id,sources:sourceEvidence(a,[...a.descendants(id)])})+(context?cardDetails(contextRow.title,local,'Global Category descendants intersected with explicit Scope Topic IDs',{identity:context.scope_type+' '+context.scope_id}):'');
 return `<section class="category-progress"><h3>Topic progress</h3>${card(title,global,definition,{details:false})}${context?card(contextRow.title,local,'Global descendants intersected with explicit Scope Topic IDs',{details:false}):''}<details open class="subcategory-breakdown"><summary>Child Categories</summary>${kids.map(child=>{const s=context?a.categoryInScope(child,context.scope_type,context.scope_id):a.category(child);return `<div class="child-progress"><button data-progress-category="${child}">${esc(a.categories.get(child).title)}</button><p>${s.state==='UNKNOWN'?'Requirements unknown':s.eligible===0?'No Topics':`${number(s.learned)} / ${number(s.eligible)} learned${s.verified?' · '+number(s.verified)+' verified':''}`}</p>${bar(s)}</div>`;}).join('')||'<p>No child Categories.</p>'}</details><p><a href="global.html?key=category%3A${id}">Show in Global Atlas ↗</a></p>${dataDetails(evidence+'<p>Child Category memberships may overlap; their counts must not be added together. Topic coverage does not establish platform-issued Category mastery.</p>')}</section>`;
}
function topic(a,id){const s=a.topic(id),value=(v,yes,no,unknown)=>v===true?yes:v===false?no:unknown;return `<section class="topic-progress"><p id="personal-status">${value(s.learned,'● Learned','○ Not learned','Learning unknown')}<br>${value(s.verified,'◎ Verified','Not verified','Verification unknown')}</p>${dataDetails(`<p>Topic ${id} · Verification status: ${s.verificationStatuses.map(esc).join(', ')||'Unknown'}</p><p>Learning source: ${esc(s.evidenceSource||'No learned evidence')}</p>${s.learningEvidence.map(e=>`<p>${esc(e.project_id?'Owner-attested Project '+e.project_id:'Direct observation')} · ${ref(e.source)} · ${esc(e.observed_at||'Date unknown')}${e.is_learned===false?' · explicitly not learned':''}</p>`).join('')}`)}</section>`;}
const api={bar,observed,official,card,scope,category,topic,overview,portfolio,completionStatus,coursePortfolio,scopeCard,scopeDetails,cardDetails,dataDetails,panelDetails};g.ProgressPresentation=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
